import{_ as n}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as o,o as i,j as e,G as t,ae as l,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const y=JSON.parse('{"title":"La Paz County Solar Energy and Job Creation Act","description":"","frontmatter":{"legisId":"2025-12-29-la-paz-county-solar-energy-and-job-creation-act","title":"La Paz County Solar Energy and Job Creation Act","displayTitle":"La Paz County Solar Energy and Job Creation Act","lawNumber":"119-68","billNumber":"H.R. 1043","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ68.xml","publishDate":"2025-12-29T00:00:00-05:00","industries":["energy","environment","government-operations"],"agencies":["Department of the Interior"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"La Paz County Solar Energy and Job Creation Act\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-29-la-paz-county-solar-energy-and-job-creation-act\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"La Paz County Solar Energy and Job Creation Act\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-29-la-paz-county-solar-energy-and-job-creation-act\\",\\"datePublished\\":\\"2025-12-29T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-29-la-paz-county-solar-energy-and-job-creation-act\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-29-la-paz-county-solar-energy-and-job-creation-act.md","filePath":"congress-bills/2025-12-29-la-paz-county-solar-energy-and-job-creation-act.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2025-12-29-la-paz-county-solar-energy-and-job-creation-act.md"},m=Object.assign(d,{setup(c){return(u,a)=>(i(),o("div",null,[a[0]||(a[0]=e("h1",{id:"la-paz-county-solar-energy-and-job-creation-act",tabindex:"-1"},[s("La Paz County Solar Energy and Job Creation Act "),e("a",{class:"header-anchor",href:"#la-paz-county-solar-energy-and-job-creation-act","aria-label":'Permalink to "La Paz County Solar Energy and Job Creation Act"'},"​")],-1)),t(n),t(r,{list:"/congress-bills"}),a[1]||(a[1]=l('<p>Signed into law on Monday, December 29, 2025. Public Law 119-68, H.R. 1043.</p><p><strong>Headline:</strong> La Paz County may buy about 3,400 acres of federal land in Arizona for solar energy and job creation.</p><p><strong>Why it matters:</strong> The law enables local development while requiring fair payment and safeguards for sensitive natural, cultural, wildlife, and recreational resources.</p><p><strong>What the law does:</strong></p><ul><li>Directs the Department of the Interior to convey eligible land after the county requests it.</li><li>Requires the county to pay fair market value and all survey, appraisal, and administrative costs.</li><li>Excludes land with significant cultural, environmental, wildlife, or recreational resources.</li><li>Preserves existing rights and allows the department to impose necessary conditions.</li><li>Requires current and future owners to minimize harm to Tribal artifacts, coordinate with the Colorado River Indian Tribes, and allow nearby reburial of unearthed artifacts.</li><li>Withdraws the land from federal mining and mineral leasing laws.</li><li>Deposits sale proceeds in the Federal Land Disposal Account for authorized uses.</li></ul><p><strong>Who it affects:</strong></p><ul><li>La Paz County and any later owners of the conveyed land.</li><li>The Colorado River Indian Tribes and people concerned with Tribal artifacts.</li><li>Users and stewards of the area’s natural, wildlife, and recreational resources.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>County residents could see land made available for solar development and related job creation.</li><li>Taxpayers do not bear the transaction costs because the county must cover them.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="la-paz-county-solar-energy-and-job-creation-act-1" tabindex="-1">La Paz County Solar Energy and Job Creation Act <a class="header-anchor" href="#la-paz-county-solar-energy-and-job-creation-act-1" aria-label="Permalink to &quot;La Paz County Solar Energy and Job Creation Act&quot;">​</a></h3><p>This law directs the Interior Department, upon La Paz County’s request, to sell the county about 3,400 acres of federally managed land in Arizona. The county must pay fair market value and all transaction costs, while land with significant cultural, environmental, wildlife, or recreational resources must be excluded.</p><p><strong>Key takeaways:</strong></p><ul><li>The Interior Department must convey the identified federal land to La Paz County as soon as practicable after the county requests it.</li><li>The conveyance remains subject to existing rights and any necessary conditions set by the Interior Department.</li><li>The county must pay the land’s appraised fair market value and all survey, appraisal, and administrative costs.</li><li>The county and any later owner must seek to avoid or minimize harm to Tribal artifacts, coordinate with the Colorado River Indian Tribes, and permit reburial of unearthed artifacts near where they were found.</li><li>The land is withdrawn from federal mining and mineral leasing laws.</li><li>Sale proceeds must be deposited in the Federal Land Disposal Account and used under the law governing that account.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ68.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ68.xml</a></p>',15))]))}});export{y as __pageData,m as default};
